<script setup lang="ts">
import PromoterIcon from './PromoterIcon.vue';
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import {units4} from './portalAmounts';
import BaseChart from './components/BaseChart.vue';
import {chartColors, donutOption, lineOption, plottedAmount} from './charts/options';
import {consumptionAnalytics as analytics} from './data/consumptionAnalytics';
type Report=Awaited<ReturnType<typeof analytics>>['data'];
type Query=Parameters<typeof analytics>[0];
const props=defineProps<{query:Query;summary:Report|null;summaryBusy?:boolean;summaryError?:boolean}>();
const emit=defineEmits<{'retry-summary':[];filter:[value:{model?:string;from:string;to:string}]}>();
const trendBusy=ref(false),rankBusy=ref(false);
const days=ref(7),trend=ref<Report|null>(null),ranking=ref<Report|null>(null),trendError=ref(false),rankError=ref(false),sync=ref(false),expanded=ref('');
const rankFrom=ref(''),rankTo=ref(''),rankPeriod=ref('today');
const colors=chartColors;
const today=()=>new Date(Date.now()+28800000).toISOString().slice(0,10);
const trendEnd=computed(()=>new Date(Date.parse(props.query.to)+28800000).toISOString().slice(0,10));
const shift=(date:string,amount:number)=>new Date(Date.parse(date+'T00:00:00Z')+amount*86400000).toISOString().slice(0,10);
const fromInstant=(date:string)=>new Date(date+'T00:00:00+08:00').toISOString();
const toInstant=(date:string)=>new Date(date+'T23:59:59.999+08:00').toISOString();
const cash=(value?:string|null)=>{if(units4(value)===null)return '—';const [w,f='']=value!.split('.');return `${w!.replace(/\B(?=(\d{3})+(?!\d))/g,',')}.${f.padEnd(2,'0').slice(0,2)}`;};
const percentage=(value?:string|null,total?:string|null)=>{const n=units4(value),d=units4(total);return n!==null&&d!==null&&d>0n?Number(n*10000n/d)/100:null;};
const rankRows=computed(()=>[...(ranking.value?.models||[])].sort((a,b)=>{const x=units4(a.amount4),y=units4(b.amount4);return x===null?1:y===null?-1:x>y?-1:x<y?1:0;}));
const shares=computed(()=>{const rows=[...(props.summary?.models||[])].sort((a,b)=>{const x=units4(a.amount4),y=units4(b.amount4);return x===null?1:y===null?-1:x>y?-1:x<y?1:0;});return rows;});
const shareOption=computed(()=>donutOption(shares.value.map(row=>({name:row.modelName||row.model||'未知模型',amount:row.amount4})),props.summary?.amount4!=null&&!props.summary.unknownAmounts));
const dates=computed(()=>Array.from({length:days.value},(_,i)=>shift(trendEnd.value,i-days.value+1)));
const trendRows=computed(()=>dates.value.map(date=>trend.value?.days?.find(row=>row.date===date)||{date,amount4:'0.0000',videoAmount4:'0.0000',imageAmount4:'0.0000'}));
const series=[{field:'amount4',label:'总消费',color:chartColors[0]},{field:'videoAmount4',label:'视频',color:chartColors[1]},{field:'imageAmount4',label:'图片',color:chartColors[2]}] as const;
const trendOption=computed(()=>lineOption(dates.value,series.map(s=>({name:s.label,values:trendRows.value.map(row=>plottedAmount(row[s.field]))}))));
let trendVersion=0,rankVersion=0;
async function loadTrend(){const own=++trendVersion;trendError.value=false;trendBusy.value=true;trend.value=null;try{const result=await analytics({...props.query,from:fromInstant(dates.value[0]!),to:props.query.to});if(own===trendVersion)trend.value=result.data;}catch{if(own===trendVersion){trend.value=null;trendError.value=true;}}finally{if(own===trendVersion)trendBusy.value=false;}}
async function loadRanking(){const own=++rankVersion;rankError.value=false;ranking.value=null;rankBusy.value=false;if(!rankFrom.value||!rankTo.value||rankFrom.value>rankTo.value){rankError.value=true;return;}rankBusy.value=true;try{const result=await analytics({...props.query,from:fromInstant(rankFrom.value),to:toInstant(rankTo.value)});if(own===rankVersion)ranking.value=result.data;}catch{if(own===rankVersion){ranking.value=null;rankError.value=true;}}finally{if(own===rankVersion)rankBusy.value=false;}}
function synchronize(){if(sync.value&&rankFrom.value&&rankTo.value&&rankFrom.value<=rankTo.value)emit('filter',{model:props.query.model,from:rankFrom.value,to:rankTo.value});}
function period(value:string,notify=true){rankPeriod.value=value;rankFrom.value=rankTo.value=shift(today(),value==='yesterday'?-1:0);void loadRanking();if(notify)synchronize();}
function custom(){rankPeriod.value='custom';void loadRanking();synchronize();}
function choose(model?:string|null){if(sync.value)emit('filter',{model:model||undefined,from:rankFrom.value,to:rankTo.value});}
watch(()=>props.query,()=>{void loadTrend();if(!rankFrom.value)period('today',false);else void loadRanking();},{deep:true,immediate:true});
watch(days,()=>void loadTrend());onBeforeUnmount(()=>{trendVersion++;rankVersion++;});
</script>
<template><section class="consumption-charts" aria-label="消费统计">
 <article class="consumption-chart-card"><h2>模型消耗占比</h2><p v-if="summaryError" class="analysis-state" role="alert">消费汇总读取失败或超时，请重试或缩小查询时间范围。<button type="button" @click="emit('retry-summary')">重试模型占比</button></p><p v-else-if="summaryBusy||!summary" class="analysis-state" role="status">正在统计模型消费，时间范围较大时可能需要更久…</p><div v-else class="consumption-share"><div class="share-chart"><BaseChart :option="shareOption" :height="200" :label="`模型消耗占比，总消费 ${cash(summary?.amount4)} 元`"/><div class="share-chart-total"><strong>{{summary?.amount4==null?'—':'¥ '+cash(summary.amount4)}}</strong><span>总消费</span></div></div><ul class="consumption-share-legend"><li v-for="(row,i) in shares" :key="`${row.type}/${row.model}`" :data-testid="summary?.amount4!=null&&!summary.unknownAmounts?'share-segment':undefined"><span class="chart-dot" :style="{background:colors[i%colors.length]}"/><span :title="row.model||undefined">{{row.modelName||row.model||'未知模型'}}</span><strong>{{percentage(row.amount4,summary?.amount4)==null?'—':percentage(row.amount4,summary?.amount4)+'%'}}</strong></li><li v-if="!shares.length">暂无模型消费</li></ul></div></article>
 <article class="consumption-chart-card"><header><h2>消费趋势</h2><div class="chart-legend"><span v-for="s in series" :key="s.field"><i class="chart-dot" :style="{background:s.color}"/>{{s.label}}</span></div><select v-model.number="days" aria-label="消费趋势时间范围"><option :value="7">近7天</option><option :value="30">近30天</option></select></header><p v-if="trendBusy" class="analysis-state" role="status">正在统计近 {{days}} 天消费趋势…</p><p v-else-if="trendError" class="analysis-state" role="alert">趋势统计读取失败或超时  <button type="button" @click="loadTrend">重试</button></p><BaseChart v-else-if="trend" :option="trendOption" :height="220" label="每日消费趋势（元）"/><details v-if="trend" class="chart-accessible-data"><summary>查看趋势数据</summary><table><caption class="sr-only">每日消费金额</caption><thead><tr><th>日期</th><th v-for="s in series" :key="s.field">{{s.label}}（元）</th></tr></thead><tbody><tr v-for="row in trendRows" :key="row.date||''"><td>{{row.date}}</td><td v-for="s in series" :key="s.field">{{cash(row[s.field])}}</td></tr></tbody></table></details></article>
 <article class="consumption-chart-card consumption-ranking"><header><h2>模型消费排行</h2><div class="rank-period"><button type="button" :aria-pressed="rankPeriod==='today'" @click="period('today')">今天</button><button type="button" :aria-pressed="rankPeriod==='yesterday'" @click="period('yesterday')">昨天</button></div></header><div class="rank-controls"><label><input v-model="sync" type="checkbox" aria-label="同步到消费明细" @change="synchronize"/>同步到消费明细</label><input v-model="rankFrom" type="date" aria-label="排行开始日期" @change="custom"/><span>→</span><input v-model="rankTo" type="date" aria-label="排行结束日期" @change="custom"/></div><p v-if="rankBusy" class="analysis-state" role="status">正在统计模型排行…</p><p v-else-if="rankError" class="analysis-state" role="alert">排行统计读取失败，请检查日期范围后重试  <button type="button" @click="loadRanking">重试</button></p><ol v-else class="consumption-rank-list"><li v-for="(row,i) in rankRows" :key="`${row.type}/${row.model}`"><span class="rank-number" :class="`rank-${i}`">{{i+1}}</span><div class="rank-model"><button type="button" :aria-label="`按${row.modelName||row.model||'未知模型'}筛选消费明细`" @click="choose(row.model)">{{row.modelName||row.model||'未知模型'}}</button><div class="rank-bar"><span :style="{width:`${percentage(row.amount4,ranking?.amount4)||0}%`,background:colors[i%colors.length]}"/></div></div><div class="rank-value"><strong>{{row.amount4==null?'—':'¥ '+cash(row.amount4)}}</strong><small>{{percentage(row.amount4,ranking?.amount4)==null?'—':percentage(row.amount4,ranking?.amount4)+'%'}}</small></div><button type="button" class="rank-expand" :aria-label="`展开${row.modelName||row.model||'未知模型'}分辨率明细`" :aria-expanded="expanded===`${row.type}/${row.model}`" @click="expanded=expanded===`${row.type}/${row.model}`?'':`${row.type}/${row.model}`"><PromoterIcon name="chevron-down"/></button><div v-if="expanded===`${row.type}/${row.model}`" class="rank-breakdown"><h3>{{row.modelName||row.model}} 分辨率明细</h3><table><thead><tr><th>分辨率</th><th>任务数</th><th>生成量</th><th>消费金额（元）</th></tr></thead><tbody><tr v-for="entry in row.resolutions||[]" :key="entry.resolution||'unknown'"><td>{{entry.resolution||'—'}}</td><td>{{entry.calls}}</td><td>{{entry.quantity==null?'—':entry.quantity+(row.type==='VIDEO'?'秒':'张')}}</td><td>{{cash(entry.amount4)}}</td></tr></tbody></table></div></li><li v-if="!ranking?.models?.length" class="chart-empty">暂无消费记录</li></ol></article>
</section></template>
